-- Patient 360 demo: Azure SQL source tables (table ingestion demo)
-- Run in Azure SQL Database, then ingest with JDBC / ADF copy activity.

CREATE TABLE dbo.patients (
    patient_id NVARCHAR(10) PRIMARY KEY,
    first_name NVARCHAR(50), last_name NVARCHAR(50),
    date_of_birth DATE, gender CHAR(1), blood_type NVARCHAR(3),
    city NVARCHAR(50), state CHAR(2), primary_physician NVARCHAR(50)
);

CREATE TABLE dbo.admissions (
    admission_id NVARCHAR(10) PRIMARY KEY,
    patient_id NVARCHAR(10) FOREIGN KEY REFERENCES dbo.patients(patient_id),
    admit_date DATE, discharge_date DATE, department NVARCHAR(50),
    diagnosis_code NVARCHAR(10), diagnosis NVARCHAR(100),
    attending_physician NVARCHAR(50), bed_type NVARCHAR(20),
    admission_type NVARCHAR(20)
);


